INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_pathway-languages-lm37','pathway-languages-lm37',1,'{"id":"pathway-languages-lm37","slug":"languages-literatures-modern-cultures-lm37-pathway","title":"Languages, Literatures and Modern Cultures LM-37 Pathway","type":"pathway","subtype":"International master''s pathway","studentSummary":"A language-and-culture master''s pathway links Ud''A with Oviedo, Rouen and Xamk through mobility, international learning, BIPs and challenge-based activity.","fullDescription":"The 2026/27 departmental call states that the pathway includes at least 25% physical Erasmus+ mobility and 25% international learning. It is embedded in the LM-37 master''s degree and can include BIPs, partner mobility and challenge-based mobility. The 20 September 2026 call deadline is now closed.","status":"Ongoing","availability":"2026/27 pathway confirmed; cited local call closed 20 September 2026","universityIds":["university-uda","university-uniovi","university-urn","university-xamk"],"hostUniversityId":"university-uda","countries":["Italy","Spain","France","Finland"],"themes":["Languages","Culture","Mobility","Challenge-based learning"],"studyLevels":["Master"],"applicationDeadline":"2026-09-20","workload":"At least 25% physical mobility and 25% international learning","actionLabel":"View the official pathway","officialUrl":"https://www.unich.it/notizie/pathway-ingenium-percorso-accademico-internazionale-gli-studenti-di-lingue-lm37","sourceId":"fc-full-uda-lm37-pathway-2026","sourceIds":["fc-full-uda-lm37-pathway-2026","fc-full-uda-lm37-call-2026"],"lastVerified":"2026-09-29","confidence":"High","dataClassification":"verified"}','Imported from the verified INGENIUM+ v1.5 dataset','fc-full-uda-lm37-pathway-2026');
