INSERT OR IGNORE INTO content_records (id,slug,type,title,summary,status,classification,confidence,owner_organization_id,source_id,official_url,published_version_id,is_published,last_verified_at) VALUES ('microcredential-from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba','from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba','microcredential','From UP2Green to UP2Learn: A Green Chemistry Learning Lab for Research-Based Education','this INGENIUM micro-credential that provides advanced training in green chemistry and sustainable chemical processes, focusing on the valorization of waste streams (e.g., CO₂, lignin, glycerol) through catalytic and materials-based approaches. Building on the research outcomes of the INGENIUM pro...','Access unverified','verified','Medium',NULL,'fc-cat-from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba','https://ingenium-university.eu/courses/from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-based-education/','version_seed_microcredential-from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba',1,'2026-10-01');
INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_microcredential-from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba','microcredential-from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba',1,'{"id":"microcredential-from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba","slug":"from-up2green-to-up2learn-a-green-chemistry-learning-lab-for-research-ba","title":"From UP2Green to UP2Learn: A Green Chemistry Learning Lab for Research-Based Education","type":"microcredential","subtype":"Green-chemistry microcredential","studentSummary":"this INGENIUM micro-credential that provides advanced training in green chemistry and sustainable chemical processes, focusing on the valorization of waste streams (e.g., CO₂, lignin, glycerol) through catalytic and materials-based approaches. Building on the research outcomes of the INGENIUM pro...","fullDescription":"this INGENIUM micro-credential that provides advanced training in green chemistry and sustainable chemical processes, focusing on the valorization of waste streams (e.g., CO₂, lignin, glycerol) through catalytic and materials-based approaches. Building on the research outcomes of the INGENIUM project UP2Green, the course integrates chemistry, materials science, and environmental process engineering into a research-based learning experience. Participants will develop knowledge on the design and application of metal nanoparticle catalysts, CO₂ capture and reuse, and sustainable process integration. The course combines asynchronous modules with joint interdisciplinary sessions, enabling learners to apply scientific concepts to real case studies. It prepares doctoral students and early-career professionals to address challenges in the green and circular economy, enhancing both research and professional competences.","status":"Access unverified","availability":"Public catalogue detail page; cu