INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_course-science-meets-industry-creative-convergence-innovating-industries-togeth','course-science-meets-industry-creative-convergence-innovating-industries-togeth',1,'{"id":"course-science-meets-industry-creative-convergence-innovating-industries-togeth","slug":"science-meets-industry-creative-convergence-innovating-industries-togeth","title":"Science Meets Industry – Creative Convergence: Innovating Industries Together","type":"course","subtype":"Science Meets Industry course","studentSummary":"By forging connections between diverse fields, this initiative exemplifies the synergy that arises when creativity meets collaboration. Students will engage in a dynamic process of innovation, journeying through three pivotal pillars of the 5Cos framework: co-ideation, co-valuation, and co-design...","fullDescription":"By forging connections between diverse fields, this initiative exemplifies the synergy that arises when creativity meets collaboration. Students will engage in a dynamic process of innovation, journeying through three pivotal pillars of the 5Cos framework: co-ideation, co-valuation, and co-design (co-test, and co-launch). These phases of the innovation process will empower participants to co-create visionary packaging solutions that are not only functional and sustainable but also tailored to the challenges posed by unconventional product shapes. The event seeks to bridge academia and industry, providing a platform where emerging talents can confront real-world challenges and propose transformative solutions.","status":"Access unverified","availability":"Public catalogue detail page; current enrolment and delivery dates require confirmation","universityIds":[],"themes":["Education","Professional learning"],"actionLabel":"Open the official course page","officialUrl":"https://ingenium-university.eu/courses/science-meets-industry-creative-convergence-innovating-industries-together/","sourceId":"fc-cat-science-meets-industry-creative-convergence-innovating-industries-togeth","sourceIds":["fc-cat-science-meets-industry-creative-convergence-innovating-industries-togeth","course-catalogue-2026"],"lastVerified":"2026-10-01","confidence":"Medium","dataClassification":"verified"}','Imported from the verified INGENIUM+ v1.5 dataset','fc-cat-science-meets-industry-creative-convergence-innovating-industries-togeth');
