INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_course-taste-italian-culture-and-language','course-taste-italian-culture-and-language',1,'{"id":"course-taste-italian-culture-and-language","slug":"a-taste-of-italian-culture-and-language","title":"A Taste of Italian Culture and Language.","type":"course","subtype":"Language and culture course","studentSummary":"!image.pngBenvenut o al corso di pre-mobilità per la lingua italiana. -o =maschile !image%20%281%29.pngBenvenut a al corso di pre-mobilità per la lingua italiana. -a =femminile This is an online Italian course for beginners, designed for international and Erasmus students comi...","fullDescription":"!image.pngBenvenut o al corso di pre-mobilità per la lingua italiana. -o =maschile !image%20%281%29.pngBenvenut a al corso di pre-mobilità per la lingua italiana. -a =femminile This is an online Italian course for beginners, designed for international and Erasmus students coming to study in Italy. The course is divided into 10 short, clear lessons. In each lesson, you will learn to communicate in real-life situations, useful for everyday and university life in Italy. During the course, you will learn to: Introduce yourself Greeting and speaking to people Understand and use important words Pronounce Italian well Learn about Italian culture and society The course is online and asynchronous: You can study whenever you want and at your own pace. Happy studying and... welcome to Italy! \\\\\\\\\\\\ Questo è un corso online di italiano per principianti, pensato per studenti internazionali ed...","status":"Access unverified","availability":"Public catalogue page; no current dates or enrolment window are stated","universityIds":["university-uda"],"hostUniversityId":"university-uda","themes":["Languages","Culture","Mobility preparation"],"deliveryMode":"Virtual","ects":0,"eligibility":"INGENIUM students and staff; check the detail page for any prerequisites","actionLabel":"Open the official course page","officialUrl":"https://ingenium-university.eu/courses/a-taste-of-italian-culture-and-language/","sourceId":"fc-cat-a-taste-of-italian-culture-and-language","sourceIds":["fc-cat-a-taste-of-italian-culture-and-language","course-catalogue-2026","fc-full-taste-courses"],"lastVerified":"2026-10-01","confidence":"High","dataClassification":"verified"}','Imported from the verified INGENIUM+ v1.5 dataset','fc-cat-a-taste-of-italian-culture-and-language');
