INSERT OR IGNORE INTO content_records (id,slug,type,title,summary,status,classification,confidence,owner_organization_id,source_id,official_url,published_version_id,is_published,last_verified_at) VALUES ('course-taste-greek-language-and-culture','taste-of-greek-language-and-culture','course','Α taste of Greek Language and Culture','The course aims at familiarizing incoming students and staff with the Greek language and culture, providing extra information about the region of Crete. It comprises ten thematic Units, two reviewing units, audio and video material, plus the links to two grammar e-companions. ...','Access unverified','verified','High','university-uoc','fc-cat-taste-of-greek-language-and-culture','https://ingenium-university.eu/courses/%ce%b1-taste-of-greek-culture-and-language/','version_seed_course-taste-greek-language-and-culture',1,'2026-10-01');
INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_course-taste-greek-language-and-culture','course-taste-greek-language-and-culture',1,'{"id":"course-taste-greek-language-and-culture","slug":"taste-of-greek-language-and-culture","title":"Α taste of Greek Language and Culture","type":"course","subtype":"Language and culture course","studentSummary":"The course aims at familiarizing incoming students and staff with the Greek language and culture, providing extra information about the region of Crete. It comprises ten thematic Units, two reviewing units, audio and video material, plus the links to two grammar e-companions. ...","fullDescription":"The course aims at familiarizing incoming students and staff with the Greek language and culture, providing extra information about the region of Crete. It comprises ten thematic Units, two reviewing units, audio and video material, plus the links to two grammar e-companions. Each unit conists of three components: a) The language component (signalled with red), which focuses on everyday spoken Greek (levels A1-A2). It is based on short texts (with their explanation and most important words or phrases). Each text serves as the basis for particular remarks about vocabulary/communication and grammar/structure. The text sub-modules are completed with basic exercises to practise on the phenomena under examination. At the end of each Unit you can find a key to the exercises. b) The cultural component (signalled with green), which focuses on attitudes, beliefs and practices of the...","status":"Access unverified","availability":"Public catalogue page; no current dates or enrolment window are stated","universityIds":["university-uoc"],"hostUniversityId":"university-uoc","themes":["Languages","Culture","Mobility preparation"],"deliveryMode":"Virtual","ects":0,"eligibility":"None","actionLabel":"Open the official course page","officialUrl":"https://ingenium-university.eu/courses/%ce%b1-taste-of-greek-culture-and-language/","sourceId":"fc-cat-taste-of-greek-language-and-culture","sourceIds":["fc-cat-taste-of-greek-language-and-culture","course-catalogue-2026","fc-full-taste-courses"],"lastVerified":"2026-10-01","confidence":"High","dataClassification":"verified"}','Imported from the verified INGENIUM+ v1.5 dataset','fc-cat-taste-of-greek-language-and-culture');
